draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.fillStyle = 'black';

  // window frame
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // window view
  ctx.fillStyle = '#87ceeb'; // light blue for sky
  ctx.fillRect(W/2-45, H/2-45, 90, 90);

  // tree outside
  ctx.fillStyle = 'green';
  ctx.fillRect(W/2-30, H/2+20, 20, 30);
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-25, H/2+50, 10, 20);

  // moving bird
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2 + 20 + Math.sin(t) * 20, H/2 - 20, 5, 0, 2 * Math.PI);
  ctx.fill();

  ctx.restore();
}
